// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    address admin;

    function setUp() public { c = new Owned(); admin = address(this); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        bool ok;
        try this.callSetOwnerAs(caller, address(0x123)) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == (caller == admin));
    }

    function callSetOwnerAs(address who, address newOwner) external {
        vm.prank(who);
        c.setOwner(newOwner);
    }
}
